    @Test fun sevenActualRootUnknownPeersBlockExistingLead()=runTest {
        Dispatchers.setMain(StandardTestDispatcher(testScheduler))
        try {for(kind in 0..6){
            val f=FixtureInboxExistingLeadPort.fromJSON(fixture("inbox-existing-lead"));val target=Held(f.grants)
            val reply=object:SyntheticInboxReplyPort {override val grants=FixtureInboxReplyPort(fixture("inbox-reply-outcome")).grants;override suspend fun execute(a:InboxReplyAttempt)=SyntheticInboxReplyOutcome.Unknown}
            val handoff=object:SyntheticHandoffPort {override val grants=FixtureHandoffPort(fixture("inbox-handoff-outcome")).grants;override suspend fun execute(a:HandoffAttempt)=SyntheticHandoffOutcome.Unknown}
            val retry=object:SyntheticInboxRetryPort {override val grants=FixtureInboxRetryPort(fixture("inbox-retry-message")).grants;override suspend fun execute(a:InboxRetryAttempt)=SyntheticInboxRetryOutcome.Unknown}
            val assign=object:SyntheticInboxSelfAssignmentPort {override val grants=FixtureInboxSelfAssignmentPort.fromJSON(fixture("inbox-self-assignment")).grants;override suspend fun execute(a:InboxSelfAssignmentAttempt)=SyntheticInboxSelfAssignmentOutcome.Unknown}
            val marker=object:SyntheticInboxReadMarkerPort {override val grants=FixtureInboxReadMarkerPort.fromJSON(fixture("inbox-read-markers")).grants;override suspend fun execute(a:InboxReadMarkerAttempt)=SyntheticInboxReadMarkerOutcome.Unknown}
            val priority=object:SyntheticInboxPriorityPort {override val grants=FixtureInboxPriorityPort.fromJSON(fixture("inbox-priority")).grants;override suspend fun execute(a:InboxPriorityAttempt)=SyntheticInboxPriorityOutcome.Unknown}
            val life=object:SyntheticInboxLifecyclePort {override val grants=FixtureInboxLifecyclePort.fromJSON(fixture("inbox-lifecycle")).grants;override suspend fun execute(a:InboxLifecycleAttempt)=SyntheticInboxLifecycleOutcome.Unknown}
            val m=InboxViewModel(Reads(),replySubmission=reply,handoffSubmission=handoff,files=files(),messageFiles=APIInboxMessageFilesRepository(FixtureInboxRetryReadTransport(fixture("inbox-retry-message"))),retrySubmission=retry,assignmentRead=APIInboxSelfAssignmentRepository(FixtureInboxSelfAssignmentReadTransport.fromJSON(fixture("inbox-self-assignment"))),assignmentSubmission=assign,markerRead=APIInboxReadMarkerRepository(FixtureInboxReadMarkerReadTransport.fromJSON(fixture("inbox-read-markers"))),markerSubmission=marker,priorityRead=APIInboxPriorityRepository(FixtureInboxPriorityReadTransport.fromJSON(fixture("inbox-priority"))),prioritySubmission=priority,lifecycleRead=APIInboxLifecycleRepository(FixtureInboxLifecycleReadTransport.fromJSON(fixture("inbox-lifecycle"))),lifecycleSubmission=life,existingLeadRead=source(),existingLeadSubmission=target)
            m.load(101,720+kind);runCurrent();m.open(901);runCurrent()
            if(kind==0){m.openReply(m.reply.state.context!!,m.control);m.reply.update(" peer reply ",m.reply.inputControl);m.reply.prepare(m.reply.control);m.reply.submit(m.reply.state.review!!,m.reply.control);m.reply.close(m.reply.returnControl)}
            else if(kind==1){m.openHandoff(m.handoff.entryControl,m.control);m.handoff.update(" peer handoff ",m.handoff.inputControl);m.handoff.prepare(m.handoff.control);m.handoff.submit(m.handoff.state.review!!,m.handoff.control);m.handoff.back(m.handoff.returnControl)}
            else if(kind==2){m.openMessageFiles(m.messageFilesEntryControl(m.state.thread!!.messages[1]));val p=m.messageMetadata!!;p.load(p.control);p.prepareRetry(p.control);p.submitRetry(p.retryReview!!,p.control);m.closeMessageFiles(m.messageFilesPresentationControl)}
            else {m.openFiles(m.filesEntryControl);val p=m.fileMetadata!!;when(kind){3->{p.loadAssignment(p.control);p.prepareAssignment(p.control);p.submitAssignment(p.assignmentReview!!,p.control)};4->{p.loadMarker(p.control);p.prepareMarker(InboxReadMarkerAction.READ,p.control);p.submitMarker(p.markerReview!!,p.control)};5->{p.loadPriority(p.control);p.choosePriority(InboxPriorityValue.HIGH,p.control);p.preparePriority(p.control);p.submitPriority(p.priorityReview!!,p.control)};else->{p.loadLifecycle(p.control);p.prepareLifecycle(InboxLifecycleAction.CLOSE,p.control);p.submitLifecycle(p.lifecycleReview!!,p.control)}};m.closeFiles(m.filesPresentationControl)}
            m.openFiles(m.filesEntryControl);val child=m.fileMetadata!!.existingLead!!;child.load(child.control);child.prepare(child.control);assertNotNull(child.source);assertFalse(child.canPrepare);assertNull(child.review);assertTrue(target.attempts.isEmpty());when(kind){0->{assertTrue("reply UNKNOWN blocks target",m.reply.submissionBlocked);assertEquals(InboxReplyPhase.UNKNOWN,m.reply.submission?.phase)};1->{assertTrue("handoff UNKNOWN blocks target",m.handoff.blocked);assertEquals(HandoffPhase.UNKNOWN,m.handoff.record?.phase)};2->{assertTrue("retry UNKNOWN blocks target",m.retryCommandsBlocked);assertEquals(InboxRetryPhase.UNKNOWN,m.messageMetadata?.retryRecord?.phase)};else->assertTrue("file command UNKNOWN kind=$kind",m.conversationCommandsBlocked)}
        }}finally{Dispatchers.resetMain()}
    }
